import csv

summe = {}
with open("verkauf.csv", newline="", encoding="utf-8") as f:
    for z in csv.DictReader(f, delimiter=";"):
        if not z["betrag"].strip():
            continue
        summe[z["region"]] = summe.get(z["region"], 0) + int(z["betrag"])
with open("summe.txt", "w", encoding="utf-8") as f:
    for r in sorted(summe):
        f.write(f"{r}: {summe[r]}\n")
